15: // applyExecutionControl will ensure a pod's execution control annotation is up-to-date
16: // kills any pending and running pods when workflow has reached it's deadline
17: func (woc *wfOperationCtx) applyExecutionControl(pod *apiv1.Pod, wfNodesLock *sync.RWMutex) {
18: 	if pod == nil {
19: 		return
20: 	}
21: 
22: 	nodeID := woc.nodeID(pod)
23: 	wfNodesLock.RLock()
24: 	node, ok := woc.wf.Status.Nodes[nodeID]
25: 	wfNodesLock.RUnlock()
26: 	if !ok {
27: 		return
28: 	}
29: 	// node is already completed
30: 	if node.Fulfilled() {
31: 		return
32: 	}
33: 	switch pod.Status.Phase {
34: 	case apiv1.PodSucceeded, apiv1.PodFailed:
35: 		// Skip any pod which are already completed
36: 		return
37: 	case apiv1.PodPending, apiv1.PodRunning:
38: 		// Check if we are currently shutting down
39: 		if woc.GetShutdownStrategy().Enabled() {
40: 			// Only delete pods that are not part of an onExit handler if we are "Stopping" or all pods if we are "Terminating"
41: 			_, onExitPod := pod.Labels[common.LabelKeyOnExit]
42: 
43: 			if !woc.GetShutdownStrategy().ShouldExecute(onExitPod) {
44: 				woc.log.WithField("podName", pod.Name).
45: 					WithField("shutdownStrategy", woc.GetShutdownStrategy()).
46: 					Info("Terminating pod as part of workflow shutdown")
47: 				woc.controller.queuePodForCleanup(pod.Namespace, pod.Name, terminateContainers)
48: 				msg := fmt.Sprintf("workflow shutdown with strategy:  %s", woc.GetShutdownStrategy())
49: 				woc.handleExecutionControlError(nodeID, wfNodesLock, msg)
50: 				return
51: 			}
52: 		}
53: 		// Check if we are past the workflow deadline. If we are, and the pod is still pending
54: 		// then we should simply delete it and mark the pod as Failed
55: 		if woc.workflowDeadline != nil && time.Now().UTC().After(*woc.workflowDeadline) {
56: 			// pods that are part of an onExit handler aren't subject to the deadline
57: 			_, onExitPod := pod.Labels[common.LabelKeyOnExit]
58: 			if !onExitPod {
59: 				woc.log.WithField("podName", pod.Name).
60: 					WithField(" workflowDeadline", woc.workflowDeadline).
61: 					Info("Terminating pod which has exceeded workflow deadline")
62: 				woc.controller.queuePodForCleanup(pod.Namespace, pod.Name, terminateContainers)
63: 				woc.handleExecutionControlError(nodeID, wfNodesLock, "Step exceeded its deadline")
64: 				return
65: 			}
66: 		}
67: 	}
68: 	if woc.GetShutdownStrategy().Enabled() {
69: 		if _, onExitPod := pod.Labels[common.LabelKeyOnExit]; !woc.GetShutdownStrategy().ShouldExecute(onExitPod) {
70: 			woc.log.WithField("podName", pod.Name).
71: 				Info("Terminating on-exit pod")
72: 			woc.controller.queuePodForCleanup(woc.wf.Namespace, pod.Name, terminateContainers)
73: 		}
74: 	}
75: }
