77: // handleExecutionControlError marks a node as failed with an error message
78: func (woc *wfOperationCtx) handleExecutionControlError(nodeID string, wfNodesLock *sync.RWMutex, errorMsg string) {
79: 	wfNodesLock.Lock()
80: 	defer wfNodesLock.Unlock()
81: 
82: 	node := woc.wf.Status.Nodes[nodeID]
83: 	woc.markNodePhase(node.Name, wfv1.NodeFailed, errorMsg)
84: 
85: 	children := []wfv1.NodeStatus{}
86: 	q := []wfv1.NodeStatus{node}
87: 	for {
88: 		if len(q) <= 0 {
89: 			break
90: 		}
91: 		childNode := q[0]
92: 		q = q[1:]
93: 		for _, nodeID := range childNode.Children {
94: 			q = append(q, woc.wf.Status.Nodes[nodeID])
95: 		}
96: 		children = append(children, childNode)
97: 	}
98: 
99: 	// if node is a pod created from ContainerSet template
100: 	// then need to fail child nodes so they will not hang in Pending after pod deletion
101: 	for _, child := range children {
102: 		if !child.IsExitNode() && !child.Fulfilled() {
103: 			woc.markNodePhase(child.Name, wfv1.NodeFailed, errorMsg)
104: 		}
105: 	}
106: }
