108: // killDaemonedChildren kill any daemoned pods of a steps or DAG template node.
109: func (woc *wfOperationCtx) killDaemonedChildren(nodeID string) {
110: 	woc.log.Infof("Checking daemoned children of %s", nodeID)
111: 	for _, childNode := range woc.wf.Status.Nodes {
112: 		if childNode.BoundaryID != nodeID {
113: 			continue
114: 		}
115: 		if !childNode.IsDaemoned() {
116: 			continue
117: 		}
118: 		podName := util.GeneratePodName(woc.wf.Name, childNode.Name, childNode.TemplateName, childNode.ID, util.GetWorkflowPodNameVersion(woc.wf))
119: 		woc.controller.queuePodForCleanup(woc.wf.Namespace, podName, terminateContainers)
120: 		childNode.Phase = wfv1.NodeSucceeded
121: 		childNode.Daemoned = nil
122: 		woc.wf.Status.Nodes[childNode.ID] = childNode
123: 		woc.updated = true
124: 	}
125: }

