func (woc *wfOperationCtx) getTransientChildren(node wfv1.NodeStatus) []wfv1.NodeStatus {
	children := []wfv1.NodeStatus{}
	q := []wfv1.NodeStatus{node}
	for {
		if len(q) <= 0 {
			break
		}
		childNode := q[0]
		q = q[1:]
		for _, nodeID := range childNode.Children {
			q = append(q, woc.wf.Status.Nodes[nodeID])
		}
		children = append(children, childNode)
	}
	return children
}

